        "version": 1
      }
    ]
  },
  "learning_request": {
    "needed": true,
    "gap": "需要2010年前可读且相关的鱼类双体轨迹方法资料，说明邻近、趋近、追随等定义及其测量条件。",
    "why_now": "现有跨物种鸭群摘要只能示范描述邻居几何，无法核验鱼类双体的操作标准；检索历史依赖的结果也不相关。",
    "queries": [
      "2010年前斑马鱼双体自由游动研究如何从质心轨迹定义成对距离或邻近状态？",
      "2010年前鱼类双体行为研究如何操作化趋近、跟随及运动方向关联，并区分观察指标与因果机制？",
      "两条动物轨迹的距离变化与各自位移如何共同报告，以避免将单体运动解释成双体互动？"
    ],
    "urls": [],
    "source_ids": [],
    "record_ids": [],
    "operations": []
  },
  "analysis_plan": {
    "kind": "analysis",
    "question": "在R07中，较近与较远距离状态之后10帧的距离变化是否不同，同时描述两标签各自10帧位移大小？",
    "record_id": "R07",
    "start": 0,
    "stop": 44999,
    "variables": [
      {
        "name": "distance",
        "expression": "norm(positions[:,0,:]-positions[:,1,:],axis=-1)",
        "meaning": "A与B坐标间二维欧氏距离",
        "units": "原生图像坐标单位"
      },
      {
        "name": "change_10",
        "expression": "shift(distance,-10)-distance",
        "meaning": "10帧后距离减当前距离，有向距离变化",
        "units": "原生图像坐标单位/10帧"
      },
      {
        "name": "A_displacement_10",
        "expression": "norm(shift(positions[:,0,:],-10)-positions[:,0,:],axis=-1)",
        "meaning": "A在10帧间隔上的位移大小",
        "units": "原生图像坐标单位/10帧"
      },
      {
        "name": "B_displacement_10",
        "expression": "norm(shift(positions[:,1,:],-10)-positions[:,1,:],axis=-1)",
        "meaning": "B在10帧间隔上的位移大小",
        "units": "原生图像坐标单位/10帧"
      },
      {
        "name": "valid_pair",
        "expression": "isfinite(distance)&isfinite(change_10)&isfinite(A_displacement_10)&isfinite(B_displacement_10)",
        "meaning": "当前及10帧后两条坐标均可用于配对",
        "units": "boolean"
      },
      {
        "name": "near_threshold",
        "expression": "quantile(distance,0.25)",
        "meaning": "R07全记录距离第25分位数",
        "units": "原生图像坐标单位"
      },
      {
        "name": "far_threshold",
        "expression": "quantile(distance,0.75)",
        "meaning": "R07全记录距离第75分位数",
        "units": "原生图像坐标单位"
      }
    ],
    "outputs": [
      {
        "name": "distance",
        "expression": "distance"
      },
      {
        "name": "future_distance_change",
        "expression": "change_10"
      },
      {
        "name": "individual_displacements",
        "expression": "A_displacement_10"
      }
    ],
    "groups": [
      {
        "name": "near",
        "where": "valid_pair&(distance<=near_threshold)",
        "values": ["distance", "change_10", "A_displacement_10", "B_displacement_10"]
      },
      {
        "name": "far",
        "where": "valid_pair&(distance>=far_threshold)",
        "values": ["distance", "change_10", "A_displacement_10", "B_displacement_10"]
      }
    ]
  },
  "memory_notes": [
    {
      "key": "coordinates_do_not_identify_behavior",
      "title": "坐标变化不等于行为机制",
      "kind": "correction",
      "mastery": "used",
      "understanding": "二维坐标支持位置、距离和位移的描述，但距离的变化不分解出各轨迹的运动贡献，也不能单独识别行为类别、感觉通路或因果互动。应将两条轨迹各自位移与距离转移并列描述。",
      "conditions": "适用于当前二维局部追踪坐标；任务、姿态、身份稳定性、帧率和物理校准未核实。",
      "example": "若A静止而B向A移动，距离会缩小；若A、B同时移动但相对位置收敛，距离也会缩小。相同距离变化不能区分这两种运动组合。",
      "open_questions": [
        "R07近远状态之后的距离变化和两标签位移分布尚未计算。",
        "当前记录中A/B身份是否稳定未知。",
        "仍不能从坐标解释距离变化对应的社会行为或感觉机制。"
      ],
      "tags": ["tracking", "distance", "behavior", "追踪", "距离", "行为", "dyad", "双体"],
      "sources": ["measurements.json"],
      "revision_reason": "在既有坐标解释边界上增加距离变化无法单独识别单体运动贡献这一具体区分，并给出反例。"
    }
  ],
  "memory_use": [
    {
      "key": "coordinates_do_not_identify_behavior",
      "source_task": "fish_001/inquiry_v2_live_20261106_002",
      "used_for": "限定距离变化和单体位移的解释，不将轨迹统计命名为追随或吸引。",
      "scope_check": "当前仍只有二维局部标签轨迹和筛选元数据；任务、身份稳定性及行为标签未核实。"
    }
  ],
  "still_cannot_explain_or_use": "仍不能解释任何潜在距离关联是否由社会互动、感觉输入或共同环境驱动；也未能使用可核验的鱼类双体轨迹方法文献。当前分析计划未执行。",
  "exploration": {
    "missing_external_facts": [
      "鱼类双体轨迹方法中邻近、趋近、追随和方向关联的日期合规操作化来源。",
      "R07的具体实验任务、场景几何、帧率、物理尺度及追踪身份稳定性。"
